    def __init__(self, ue_id):
        """
        Basic initialization.
        :param ue_id:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'USB', 'ue_id': ue_id})
        self.logger.propagate = False
        self.ue_id = ue_id
        adb.adb_start_mobile_app(self.ue_id)
        self.sock_thread = SendReceiveSocketControlThread(ue_id)
        self.sock_thread.start()
        self.sock_thread.wish_to_send_msg(self.GET_ANDROID_VERSION, "", block_unitl_send=False,
                                          resend_on_reconnect=True)
        self.sock_thread.wish_to_send_msg(self.GET_ANDROID_SDK, "", block_unitl_send=False,
                                          resend_on_reconnect=True)
        self.sock_thread.wish_to_send_msg(self.GET_APP_VERSION, "", block_unitl_send=False, resend_on_reconnect=True)
        self.cmd_id_gen = CmdIdGenerator()
        self.network_interface_parser = NetworkInterfacesParser()
        self.mobile_app_protocol_version = self.get_mobile_app_protocol_version()
        self.is_qualcomm_prototype = None

    def __del__(self):
        try:
            class_name = self.__class__.__name__
            self.close()
            self.logger.debug("Object of class {} destroyed".format(class_name))
        except Exception as e:
            self.logger.debug(str(e))
            raise

    def close(self):
        """
        :param func:
        :return:
        """
        self.sock_thread.close()

    def clear_reconnect_queue(self):
        """Clears queue of msgs to resend on reconnect to UE."""
        self.sock_thread.clear_reconnect_queue()

    def __enter__(self):
        self.logger.debug("__enter__ for ue %s invoked" % self.ue_id)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.logger.debug("__exit__ from ue %s invoked" % self.ue_id)
        self.close()
        return False

    def sleep(self, sleeptime=0):
        """
        :param func:
        :return:
        """
        time.sleep(sleeptime)

