        ue_firmware_version = self.sock_thread.get_info(self.GET_UE_FIRMWARE_VERSION)
        if ue_firmware_version:
            return ue_firmware_version
        self.logger.debug("sending: GET_UE_FRIMWARE_VERSION")
        ue_firmware_version = self.send_message_get(self.GET_UE_FIRMWARE_VERSION)
        self.logger.debug('UE_FIRMWARE_VERSION={}'.format(ue_firmware_version))
        return ue_firmware_version

