    @staticmethod
    def _verify_json_action_response(result, action, allowed_responses):
        if result not in allowed_responses:
            raise InvalidJsonActionResponse(result, action, allowed_responses)

    def is_emergency_phone_number(self, phone_number):
        """
        Verifies whether phone number is an emergency one. We need to use the app here because it check the current
        country emergency numbers based on current PLMN.
        """
        action_name = JsonProtocolActions.IS_EMERGENCY_CALL_NUMBER
        try:
            is_emergency_phone_number_action_request_msg = \
                self._get_action_request_message(action_name, {"arguments": {"phoneNumber": phone_number}})
            result = self.send_json_action_and_get_result(is_emergency_phone_number_action_request_msg)
            self._verify_json_action_response(result, action_name, [True, False])
        except Exception as exc:
            self.logger.info("Fault getting is_emergency_phone_number (Please verify if NAA is updated): {}".format(exc))
            return False
        return result

    def is_in_call(self):
        action_name = JsonProtocolActions.IS_IN_CALL
        is_in_call_action_request_msg = self._get_action_request_message(action_name)
        result = self.send_json_action_and_get_result(is_in_call_action_request_msg)
        self._verify_json_action_response(result, action_name, [True, False])
        return result

    def set_network(self, network):
        """
        :param func:
        :return:
        """
        body = '%d' % (self._get_network_mode_number(network) + self.PREFERRED_NETWORK_MODE_LEGACY_OFFSET)
        self.sock_thread.wish_to_send_msg(self.SET_PREFERRED_NETWORK_MODE, body)

