    def send_message_get(self, message, msg_validator=lambda msg: True):
        """
        :param message: message to send
        :param msg_validator function used to check if this is the awaited msg
        :return:
        """
        if not self.sock_thread.await_fresh_heartbeats(timeout=30, should_raise=False):
            adb.adb_devices()
            adb.adb_restart_mobile_app(self.ue_id)
        self.sock_thread.await_fresh_heartbeats()
        msg_id = message[0]
        packet_body = message[1:]
        if not packet_body:
            packet_body = ''
        info = self.sock_thread.wait_until_info_update_and_get_info(msg_id, msg_validator=msg_validator,
                                                                    get_info_packet_body=packet_body)
        self.logger.debug('Message: {} sent, info gotten: {}'.format(message, info))
        return info

    def send_message_set(self, message):
        """
        :param func:
        :return:
        """
        self.sock_thread.await_fresh_heartbeats()
        self.send_message(message)
        self._wait_until_ready_to_send_cmd()

