    def receive_sms(self):
        """
        Pops some SMS captured by mobile app.
        :return: bool, string, string: success, fromAddress, msgBody
        """
        sms = self.check_sms()
        parts = sms.split("|")
        if parts[0] == 'NO_SMS':
            return False, None, None
        if parts[0] == 'GOT_EXCEPTION':
            raise Exception("Got exception while parsing incoming sms: {}".format(sms))
        if parts[0] == 'NEW_SMS':
            number = parts[1]
            body = parts[2:]
            return True, number, "".join(body)
        raise Exception("Unexpected result from mobile app: {}".format(sms))

    def check_sms(self):
        """
        Low level protocol method to get raw output from UE after as response to CHECK_SMS.
        :return:
        """
        return self.send_message_get(self.CHECK_SMS)

