    def set_auto_call_answering(self, call_answering):
        """
        Setts on UE auto_call_answering.
        Does not checks if changed.
        :param call_answering: bool
        :return:
        """
        if call_answering:
            call_answering = '1'
        else:
            call_answering = '0'
        timeout = 15
        self.sock_thread.wish_to_send_msg(self.SET_AUTO_CALL_ANSWERING, call_answering, resend_on_reconnect=False,
                                          block_unitl_send=timeout, block_unitl_send_timeout=timeout)

    def is_auto_call_answering(self):
        """
        Checks if auto call answering is turn on UE.
        :return: bool
        """
        return self.send_message_get(self.GET_AUTO_CALL_ANSWERING) == '1'

    def list_voice_calls_uris(self):
        """
        ...
        :return:
        """
        result = self.send_message_get(self.LIST_VOICE_CALLS_URIS)
        if result == '':
            return []
        voice_calls_list = result.split('|')
        voice_calls_list = {v: v for v in voice_calls_list}.keys()
        return list(voice_calls_list)

    def action_on_voice_calls(self, action_name, uri):
        """
        ...
        :param action_name:
        :param uri:
        :return:
        """
        if uri == '':
            raise Exception("empty uri")
        packet_body = action_name + "|" + uri
        self.sock_thread.await_fresh_heartbeats()
        result = self.sock_thread.wait_until_info_update_and_get_info(self.ACTION_ON_VOICE_CALL,
                                                                      get_info_packet_body=packet_body)
        if result.startswith(self.VOICE_CALL_RESULT_EXCEPTION):
            msg = result[len(self.VOICE_CALL_RESULT_EXCEPTION):]
            raise Exception(msg)
        self.logger.debug('action on voice call took on: {}, result: {}'.format(action_name, result))
        return result

    def voice_call_hold(self, uri):
        """
        ...
        :param uri:
        :return:
        """
        return self.action_on_voice_calls("HOLD", uri)

    def voice_call_unhold(self, uri):
        """
        ...
        :param uri:
        :return:
        """
        return self.action_on_voice_calls("UNHOLD", uri)

    def voice_call_answer(self, uri, with_video=False):
        """
        ...
        :param uri:
        :param with_video:
        :return:
        """
        if not with_video:
            return self.action_on_voice_calls("ANSWER", uri)
        return self.action_on_voice_calls("ANSWER_WITH_VIDEO", uri)

